App.register({group:'studio',label:'05 / AI 创作工作台',routes:[{path:'studio/brief',title:'AI 创作助手',icon:'✳',permission:'studio',render(){const p=DB.projects.find(x=>x.id===DB.state.projectId)||DB.projects[0];return UI.page('CREATIVE DESK / 01','AI 创作助手','用自然语言描述你的创作目标，AI 组织创意、剧本与后续专业生产。',UI.btn('项目档案','go:workspace/detail','btn'),`<div class="grid grid-2"><div class="card"><div class="eyebrow">CURRENT PROJECT / ${p.id}</div><h2 style="font-size:20px;margin:8px 0">${p.title}</h2><p class="small muted">${p.genre} · ${p.episodes} 集 · 归属 ${DB.tenants.find(t=>t.id===p.tenant)?.name||'历史空间'}</p><div class="divider"></div><label class="field-wrap"><span class="field-label">创作需求描述</span><textarea class="field" rows="6" placeholder="例如：一部 12 集都市悬疑短剧。女主收到已故父亲发来的定时语音，逐步发现旧城区拆迁背后的秘密……"></textarea></label><div class="grid grid-2 section-gap"><label class="field-wrap"><span class="field-label">目标受众</span><select class="field"><option>18–35 岁都市观众</option><option>女性成长向</option><option>泛悬疑受众</option></select></label><label class="field-wrap"><span class="field-label">视觉风格</span><select class="field"><option>电影感写实</option><option>高饱和商业短剧</option><option>国风美学</option></select></label></div><div class="section-gap">${UI.btn('✳ 生成创意与剧本','script:generate','btn-lime')}</div><div class="tiny muted section-gap">演示交互：按钮改变项目阶段状态，不调用真实模型。</div></div><div class="card card-dark"><div class="eyebrow" style="color:var(--lime)">AI ORCHESTRATOR</div><h2 style="font-size:19px;margin:8px 0 12px">你的 AI 制作统筹</h2><p class="small" style="color:#aebbc2;line-height:1.8">平台会把创作需求拆解为可追溯的生产对象，而不是把多个孤立 AI 工具简单堆在一起。</p><div class="divider" style="background:#33404a"></div>${['分析题材与受众定位','构建故事世界观与人物关系','规划分集剧情与集尾钩子','生成完整剧本及对白','预检逻辑、内容与版权风险'].map((x,i)=>`<div class="kpi-line" style="border-color:#33404a"><span style="color:#c6d1d4">${String(i+1).padStart(2,'0')} / ${x}</span><span style="color:var(--lime)">AI</span></div>`).join('')}<div class="notice dark section-gap">人工正式审核点：剧本确认。审核通过后才进入正式生产。</div></div></div><div class="grid grid-3 section-gap"><div class="card"><div class="card-title">创作输入</div><p class="small muted">题材、核心冲突、人物关系、受众、集数和风格偏好。</p></div><div class="card"><div class="card-title">AI 生成资产</div><p class="small muted">故事大纲、世界观、人物档案、分集剧情、正式剧本候选版本。</p></div><div class="card"><div class="card-title">人工决策</div><p class="small muted">确认故事方向、内容合规与剧本正式版本；不承担专业编剧执行。</p></div></div>`); }},{path:'studio/script-review',title:'剧本审核',icon:'▤',permission:'studio',render(){if(DB.state.tenant!=='tn-north')return UI.page('HUMAN GATE / SCRIPT','当前租户暂无待审剧本','剧本审核只展示当前租户及授权项目的待决事项。','',`<div class="card">${UI.empty('暂无待审核剧本','切换到有待审核项目的授权租户。')}</div>`);return UI.page('HUMAN GATE / SCRIPT','剧本审核台','人工审核节点 A：确认故事方向、分集结构、人物设定、逻辑与合规后锁定正式版本。',UI.btn('打开创作助手','go:studio/brief','btn'),`<div class="notice warn">剧本审核是正式生产前的人工决策门。未审核通过的剧本不能启动导演分镜与后续生产。</div><div class="grid grid-3 section-gap">${UI.metric('待审核剧本','01','当前演示队列','▤')}${UI.metric('剧本版本','V3','候选正式版本','↗')}${UI.metric('AI 预检结果','通过','逻辑 / 内容 / 版权提示','✓')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-head"><div><div class="card-title">《雾城来信》· 剧本 V3</div><div class="card-sub">12 集 · 都市悬疑 · 约 18 分钟 / 集</div></div>${UI.tag(DB.state.scriptApproved?'已通过':'待审核',DB.state.scriptApproved?'green':'orange')}</div><div class="tabs"><button class="tab active" data-action="tab" data-target="outline">故事大纲</button><button class="tab" data-action="tab" data-target="episodes">分集结构</button><button class="tab" data-action="tab" data-target="risk">合规预检</button></div><div data-tab-panel="outline"><h3 class="section-title">核心故事</h3><p class="small" style="line-height:1.9;color:#58656c">女主林晚在父亲去世三年后，收到一段来自旧城区的定时语音。她循着语音线索回到即将拆迁的街区，发现父亲留下的录音并非遗言，而是一份关于旧案的证据链。每一次回访都让她接近真相，也迫使她重新理解父亲。</p><div class="divider"></div><div class="small"><b>人物弧光：</b>从逃避真相到主动揭开家族秘密。</div></div><div data-tab-panel="episodes" hidden><div class="kpi-line"><span>01–03 集 · 悬念建立</span><b>3 集</b></div><div class="kpi-line"><span>04–08 集 · 线索反转</span><b>5 集</b></div><div class="kpi-line"><span>09–12 集 · 真相与和解</span><b>4 集</b></div></div><div data-tab-panel="risk" hidden><div class="kpi-line"><span>剧情逻辑检查</span>${UI.tag('通过','green')}</div><div class="kpi-line"><span>敏感内容检查</span>${UI.tag('需人工确认 1 项','orange')}</div><div class="kpi-line"><span>版权素材检查</span>${UI.tag('未发现引用素材','green')}</div></div><div class="divider"></div><div class="small muted">版本差异：V3 调整第 4 集动机铺垫，补充第 8 集反转伏笔；保留 V1 / V2 历史版本。</div></div><div class="card"><div class="card-title">审核决策</div><div class="callout"><div class="callout-icon">✓</div><div><strong>AI 预检摘要</strong><p>故事主线闭环；主要人物动机明确；分集节奏满足短剧结构。第 6 集有一处因果关系建议复核。</p></div></div><div class="field-wrap section-gap"><span class="field-label">审核意见</span><textarea class="field" placeholder="填写通过意见或退回修改建议"></textarea></div><div class="grid grid-2 section-gap">${UI.btn('退回修改','script:return', 'btn')}${UI.btn(DB.state.scriptApproved?'已确认正式版本':'通过并锁定 V3','script:approve','btn-lime')}</div><p class="tiny muted section-gap">通过后形成不可变更的正式版本快照，后续修改将创建新版本并触发影响分析。</p></div></div>`);}}]});
